const payload = $('Execute Workflow Trigger').item.json || {};
const chatId = String(payload.chatId || payload.message?.chat?.id || '').trim();
const query = String(payload.query || payload.text || payload.rawText || '').trim();
const limit = Math.max(1, Math.min(5, Number(payload.limit || 5) || 5));
const escapeSql = (value = '') => String(value || '').replace(/'/g, "''");
if (!chatId) {
  throw new Error('Missing chatId for memory_recall_episodes');
}
if (!query) {
  return [{ json: { chatId, query: '', skip: true, responseText: 'MEMORY_EPISODE_RESULTS\nnone' } }];
}
const q = escapeSql(query);
const searchSql = `SELECT episode_summary, topic, tags, importance, episode_date, updated_at FROM mia_episodes WHERE chat_id = '${escapeSql(chatId)}' AND (episode_summary ILIKE '%${q}%' OR topic ILIKE '%${q}%' OR array_to_string(tags, ' ') ILIKE '%${q}%') ORDER BY CASE WHEN episode_summary ILIKE '${q}%' THEN 0 ELSE 1 END, importance DESC, updated_at DESC LIMIT ${limit};`;
return [{ json: { chatId, query, skip: false, searchSql } }];

const source = $('Prepare Recall Episodes').item.json || {};
if (source.skip) {
  return [{ json: { text: source.responseText, chatId: source.chatId || '' } }];
}
const rows = $input.all().map((item) => item.json || {}).filter((row) => row.episode_summary);
if (rows.length === 0) {
  return [{ json: { text: `MEMORY_EPISODE_RESULTS\nquery: ${source.query}\nnone`, chatId: source.chatId || '' } }];
}
const lines = ['MEMORY_EPISODE_RESULTS', `query: ${source.query}`];
rows.forEach((row, index) => {
  const tags = Array.isArray(row.tags) && row.tags.length ? ` | tags=${row.tags.join(', ')}` : '';
  const datePart = row.episode_date ? ` | date=${row.episode_date}` : '';
  lines.push(`${index + 1}. [${row.topic || 'general'}] ${row.episode_summary}${datePart}${tags}`);
});
return [{ json: { text: lines.join('\n'), chatId: source.chatId || '' } }];
